#include <vector>
#include <cstddef>

template <class T>
class ObjectPool {
    std::vector<T>  storage_;   // contiguous backing store, sized once
    std::vector<T*> free_;      // stack of available slots
public:
    explicit ObjectPool(size_t n) : storage_(n) {
        free_.reserve(n);
        for (size_t i = 0; i < n; ++i) free_.push_back(&storage_[i]);
    }
    // O(1), no heap allocation; nullptr if exhausted.
    T* acquire() noexcept {
        if (free_.empty()) return nullptr;
        T* p = free_.back();
        free_.pop_back();
        return p;
    }
    // O(1) return to pool.
    void release(T* p) noexcept { free_.push_back(p); }
    size_t available() const noexcept { return free_.size(); }
};

#include <cstddef>
#include <new>
#include <vector>

template <class T, size_t N>
class ObjectPool {
    union Slot { Slot* next; alignas(T) unsigned char storage[sizeof(T)]; };
    std::vector<Slot> slots_{N};
    Slot* free_ = nullptr;
public:
    ObjectPool() { for (size_t i = 0; i < N; ++i) { slots_[i].next = free_; free_ = &slots_[i]; } }

    template <class... Args>
    T* alloc(Args&&... args) {                  // O(1), no heap
        if (!free_) return nullptr;             // exhausted -> fail fast / back-pressure
        Slot* s = free_; free_ = s->next;
        return ::new (s->storage) T(std::forward<Args>(args)...);  // placement new
    }
    void free(T* p) {                           // O(1)
        p->~T();                                // explicit destruction
        Slot* s = reinterpret_cast<Slot*>(p);
        s->next = free_; free_ = s;             // push back on free-list
    }
};

#include <cstddef>
#include <cstdint>

class Arena {
    std::byte* buf_; size_t cap_, off_ = 0;
public:
    Arena(std::byte* buf, size_t cap) : buf_(buf), cap_(cap) {}
    void* alloc(size_t n, size_t align = alignof(std::max_align_t)) {
        size_t p = (off_ + (align - 1)) & ~(align - 1);   // align up
        if (p + n > cap_) return nullptr;                 // out of arena
        off_ = p + n;                                     // bump
        return buf_ + p;
    }
    void reset() { off_ = 0; }   // free EVERYTHING at once (call dtors first if needed)
};
// Per event: allocate scratch from the arena, process, then arena.reset().
